# reconstruct target mark map and fill adjacent diagonal bands using x=r+c, d=c-r
rows=[[8]*16 for _ in range(16)]
tracks={7:(7,23),3:(7,23),-2:(10,20),-7:(13,15)}
marks=[(0,7),(1,8),(2,5),(2,9),(3,6),(3,10),(4,7),(4,11),(5,8),(5,12),(6,4),(6,9),(6,13),(7,5),(7,10),(7,14),(8,6),(8,11),(8,15),(9,7),(9,12),(10,3),(10,8),(10,13),(11,4),(11,9)]
for r,c in marks: rows[r][c]=5
for low,high in [(-7,-2),(-2,3),(3,7)]:
    xa=max(tracks[low][0],tracks[high][0]); xb=min(tracks[low][1],tracks[high][1])
    for r in range(16):
        for c in range(16):
            x=r+c; d=c-r
            if xa<=x<=xb and low<d<high and rows[r][c]==8: rows[r][c]=2
print('\n'.join(' '.join(map(str,row)) for row in rows))

rows=[[8]*16 for _ in range(16)]
tracks={7:(7,23),3:(7,23),-2:(10,20),-7:(13,15)}
marks=[(0,7),(1,8),(2,5),(2,9),(3,6),(3,10),(4,7),(4,11),(5,8),(5,12),(6,4),(6,9),(6,13),(7,5),(7,10),(7,14),(8,6),(8,11),(8,15),(9,7),(9,12),(10,3),(10,8),(10,13),(11,4),(11,9)]
for r,c in marks: rows[r][c]=5
levels=sorted(tracks)
for i,a in enumerate(levels):
 for b in levels[i+1:]:
  xa=max(tracks[a][0],tracks[b][0]); xb=min(tracks[a][1],tracks[b][1])
  if xa>xb: continue
  for r in range(16):
   for c in range(16):
    x=r+c; d=c-r
    if xa<=x<=xb and a<d<b and rows[r][c]==8: rows[r][c]=2
print('\n'.join(' '.join(map(str,row)) for row in rows))
